type TreeNode struct {
	Val   int
	Left  *TreeNode
	Right *TreeNode
}

func isNull(s string) bool { return s == "null" || s == "None" || s == "#" }

// 层序数组建树：null 表示空节点，不要给它建孩子
func build(tok []string) *TreeNode {
	if len(tok) == 0 || isNull(tok[0]) {
		return nil
	}
	v, _ := strconv.Atoi(tok[0])
	root := &TreeNode{Val: v}
	q := []*TreeNode{root}
	for i := 1; i < len(tok) && len(q) > 0; {
		node := q[0]
		q = q[1:]
		if !isNull(tok[i]) {
			x, _ := strconv.Atoi(tok[i])
			node.Left = &TreeNode{Val: x}
			q = append(q, node.Left)
		}
		i++
		if i < len(tok) && !isNull(tok[i]) {
			x, _ := strconv.Atoi(tok[i])
			node.Right = &TreeNode{Val: x}
			q = append(q, node.Right)
		}
		i++
	}
	return root
}

