func main() {
	data, _ := os.ReadFile("/dev/stdin")
	tok := strings.Fields(string(data))
	p := 0
	n, _ := strconv.Atoi(tok[p])
	p++
	m, _ := strconv.Atoi(tok[p])
	p++
	g := make([][]int, n+1)
	for i := 0; i < m; i++ {
		u, _ := strconv.Atoi(tok[p])
		p++
		v, _ := strconv.Atoi(tok[p])
		p++
		g[u] = append(g[u], v)
		g[v] = append(g[v], u) // 无向图才加这一行
	}

	seen := make([]bool, n+1)
	cnt := 0
	for s := 1; s <= n; s++ {
		if seen[s] {
			continue
		}
		cnt++
		q := []int{s}
		seen[s] = true
		for len(q) > 0 {
			u := q[0]
			q = q[1:]
			for _, v := range g[u] {
				if !seen[v] {
					seen[v] = true
					q = append(q, v)
				}
			}
		}
	}
	fmt.Println(cnt)
