type MinStack struct{ a []int }

func (s *MinStack) Push(v int) { s.a = append(s.a, v) }
func (s *MinStack) Pop()       { s.a = s.a[:len(s.a)-1] }
func (s *MinStack) GetMin() int {
	mn := s.a[0]
	for _, v := range s.a[1:] {
		if v < mn {
			mn = v
		}
	}
	return mn
}

func main() {
