	p++
	st := &MinStack{}
	out := []string{}
	for ; q > 0; q-- {
		op := tok[p]
		p++
		switch op {
		case "push":
			v, _ := strconv.Atoi(tok[p])
			p++
			st.Push(v)
		case "pop":
			st.Pop()
			out = append(out, "null")
		default: // top / getMin / get
			out = append(out, strconv.Itoa(st.GetMin()))
		}
	}
	fmt.Println(strings.Join(out, "\n"))
