)

type IntHeap []int

func (h IntHeap) Len() int            { return len(h) }
func (h IntHeap) Less(i, j int) bool  { return h[i] < h[j] }
func (h IntHeap) Swap(i, j int)       { h[i], h[j] = h[j], h[i] }
func (h *IntHeap) Push(x interface{}) { *h = append(*h, x.(int)) }
func (h *IntHeap) Pop() interface{} {
	old := *h
	x := old[len(old)-1]
	*h = old[:len(old)-1]
	return x
}

func main() {
	data, _ := os.ReadFile("/dev/stdin")
	tok := strings.Fields(string(data))
	n, _ := strconv.Atoi(tok[0])
	k, _ := strconv.Atoi(tok[1])
	h := &IntHeap{}
	heap.Init(h)
	for i := 0; i < n; i++ {
		v, _ := strconv.Atoi(tok[2+i])
		heap.Push(h, v)
		if h.Len() > k { // 只留 k 个，堆顶就是第 k 大
			heap.Pop(h)
		}
	}
	fmt.Println((*h)[0])
}

